/* M7.101: one access of a program -- at T `ins` + k, k T into its instruction (cp.k, beside it).  A lazy block needs
   the instruction: the machine takes an interrupt at an instruction's END, so the accesses of the one in progress at
   the point are made BEFORE the ISR (lzSeg) */
function bbAcc(cp, ins, k){
  cp.push(ins + k);
  if (cp.k) cp.k.push(k);
}
/* $7F80's accesses, instruction by instruction (SkoolKit's access lists: an opcode fetch at 0, an operand at 4
   and 7, a CALL's high byte again at 10, a taken JR's five cycles on its offset 7..11, DJNZ's 5 and 8..12);
   the data it reads and writes ($8609, $9A0E, $E0xx, the ROM's glyphs) is not contended.  Returns its T. */
function bbDigitsCp(cp, rnd){
  let t = 0;
  const ins = (n, pts) => { for (const d of pts) bbAcc(cp, t, d); t += n; };
  const OP = [0], N = [0, 4], NN = [0, 4, 7], CALL = [0, 4, 7, 10], JR = [0, 4, 7, 8, 9, 10, 11];
  const glyph = () => {                                 // $7FAF INC HL / EX DE,HL / INC H / LD B,7
    ins(6, OP); ins(4, OP); ins(4, OP); ins(7, N);
    for (let r = 0; r < 7; r++){                        // LD A,(DE) / LD (HL),A / INC H / INC DE / DJNZ
      ins(7, OP); ins(7, OP); ins(4, OP); ins(6, OP);
      if (r < 6) ins(13, [0, 5, 8, 9, 10, 11, 12]); else ins(8, [0, 5]);
    }
    ins(7, N); ins(13, NN); ins(10, OP);                // LD A,7 / LD ($F841),A / RET
  };
  const sub = () => { ins(17, CALL); t += BB_EXT_CP.DIG_SUB; };   // CALL $8042
  ins(13, NN); ins(7, N);                               // $7F80 LD A,($8609) / CP $51
  if (rnd === 0x51){ ins(11, OP); return t; }           // $7F85 RET z, taken
  ins(5, OP); ins(7, N);                                // RET z / LD E,$FF
  const tens = (rnd / 10) | 0;
  for (let k = 0; k <= tens; k++){                      // $7F88 INC E / SUB 10 / JR nc
    ins(4, OP); ins(7, N);
    if (k < tens) ins(12, JR); else ins(7, N);
  }
  ins(7, N); ins(11, OP); ins(4, OP); ins(4, OP);       // ADD A,10 / PUSH AF / LD A,E / OR A
  if (tens){
    ins(7, N); sub(); ins(13, NN); ins(10, NN); ins(17, CALL); glyph();   // JR z / the tens / LD DE / CALL $7FAF
    ins(7, N); ins(13, NN);                             // $7FA0 LD A,7 / LD ($F840),A
  } else ins(12, JR);                                   // $7F92 JR z, taken
  ins(10, OP); sub(); ins(13, NN); ins(10, NN); glyph();   // POP AF / the units / LD DE / $7FAF fallen into
  return t;
}
