/* M10.2a: the 128K cold start's program (BB_M128.COLD), decoded as bbColdProg decodes the 48K's */
function bbCold128Prog(){
  const C = BB_M128.COLD, s = bbUnlz(b64(C.LZ)), out = [];
  let i = 0, at = 0;
  while (i < s.length){
    let d = 0, sh = 0, c;
    do { c = s[i++]; d += (c & 0x7F) * Math.pow(2, sh); sh += 7; } while (c & 0x80);
    out.push(at += d);
  }
  if (out.length !== C.N) throw new Error('bbCold128Prog: ' + out.length + ' accesses, the 128K cold start makes ' + C.N);
  return Int32Array.from(out);
}
let bbCold128ProgC = null;
/* $F5CC -> $8CCA on the 128K leg begun at `phase` of the frame: PLAIN + the program's waits replayed from there; with
   `upto`, the T to that plain offset (an instruction's first T: the waits of the accesses before it) */
function bbColdT128(phase, upto){
  const Q = bbCold128ProgC = bbCold128ProgC || bbCold128Prog();
  const end = upto === undefined ? BB_M128.COLD.PLAIN : upto;
  let w = 0;
  for (let i = 0; i < Q.length && Q[i] < end; i++) w += bbUlaDelay(phase + Q[i] + w);
  return end + w;
}
/* OUT (C),A with BC = $7FFD on the 48K clock: the port's high byte $7F is in $40..$7F and its low bit set, so its I/O
   cycle is contended C:1, C:1, C:1, C:1 from 8 T into the instruction (its two opcode fetches above $8000 wait nothing):
   the waits of an OUT whose first T is `t` (SkoolKit's io_contention_48k; the flow's p7ffd rows) */
function bbIo7ffd(t){
  let p = t + 8, d = 0;
  for (let i = 0; i < 4; i++){ const w = bbUlaDelay(p); d += w; p += w + 1; }
  return d;
}

