    ram[0x9D8B] = 0xC9;                              // $9D18 LD ($9D8B),A -- RET
    this.projBreath(iy);                             // $9D1B CALL $9C4B
    ram[0x9D5C] = 0x00;                              // $9D1E XOR A / $9D1F LD ($9D5C),A -- NOP
