    a = (a & 0xFF00) | ((a + 1) & 0xFF);             // $9D33 INC L -- EIGHT bit
    ram[a] = 0x42;                                   // $9D34 LD (HL),A
    a = (a + 0x1F) & 0xFFFF;                         // $9D2F LD BC,$1F / $9D35 ADD HL,BC
    ram[a] = 0x42;                                   // $9D36 LD (HL),A
    a = (a & 0xFF00) | ((a + 1) & 0xFF);             // $9D37 INC L
    ram[a] = 0x42;                                   // $9D38 LD (HL),A / $9D39 RET
